mapper.select:
SELECT u.id, u.type, u.login_id, u.password, u.fullname, u.gender, u.birthday, u.mobile, u.email, u.address, u.profile_img, u.session_id, u.auto_login_limit, u.wrong_password_count, u.created_at, u.updated_at, u.deleted_at, c.name, le.id as leId, le.completion_status as leCompletionStatus, c.id as courseId, c.name as courseName FROM user u INNER JOIN learner_enrollment le ON u.id = le.user_id LEFT JOIN course c ON le.course_id = c.id LEFT JOIN staff_assignment sa ON le.course_id = sa.course_id LEFT JOIN staff_detail sd ON sa.user_id = sd.user_id WHERE u.type = 'LEARNER' AND ( CASE WHEN (sd.position = 'GENERAL_MANAGER') THEN 1=1 WHEN (sd.position IN ('COURSE_HEAD', 'FULLTIME_INSTRUCTOR')) THEN sa.user_id = #{loginUserId} ELSE 1=0 END )
AND u.fullname LIKE CONCAT('%', #{pageUserReqDTO.keyword}, '%')
AND c.is_in_progress = #{isInProgress}
AND c.id = #{courseId}
ORDER BY ${pageUserReqDTO.orderBy} ${pageUserReqDTO.orderDirection}
LIMIT #{pageUserReqDTO.offset}, #{pageUserReqDTO.pageSize}

SELECT DISTINCT le.id as leId, le.completion_status as leCompletionStatus,
u.id as userId, u.fullname as userFullname, u.birthday as userBirthday, u.mobile as userMobile, u.email as userEmail, u.address as userAddress, u.gender as userGender, u.profile_img as userProfileImg,
es.id as esId, es.is_counseling_received as esIsCounselingReceived, es.counseling_details as esCounselingDetails, es.employment_status as esEmploymentStatus, es.company_name as esCompanyName, es.company_phone as esCompanyPhone, es.company_address as esCompanyAddress,
c.id as courseId, c.is_in_progress as courseIsInProgress, c.name as courseName
FROM learner_enrollment le
INNER JOIN user u ON le.user_id = u.id INNER JOIN course c ON le.course_id = c.id LEFT JOIN employment_support es ON le.id = es.learner_enrollment_id LEFT JOIN staff_assignment sa ON le.course_id = sa.course_id LEFT JOIN staff_detail sd ON sa.user_id = sd.user_id
WHERE
AND u.fullname LIKE CONCAT('%', #{pageLearnerReqDTO.keyword}, '%')
AND c.is_in_progress = #{isInProgress}
AND c.id = #{courseId}
AND le.id = #{leId}
ORDER BY ${pageLearnerReqDTO.orderBy} ${pageLearnerReqDTO.orderDirection}
LIMIT #{pageLearnerReqDTO.offset}, #{pageLearnerReqDTO.pageSize}

mapper.sql:
(
  u.id = #{loginUserId}
  OR (
  CASE
  WHEN (sd.position = 'GENERAL_MANAGER') THEN 1=1
  WHEN (sd.position IN ('COURSE_HEAD', 'FULLTIME_INSTRUCTOR')) THEN sa.user_id = #{loginUserId}
  ELSE 1=0
  END
  )
)
